#!/bin/bash
#
# LifeKit 管理服务 —— 一键安装（Ubuntu / Debian）
#
# 用法：把整个文件内容复制，在服务器上执行：
#   bash install.sh
#
# 它会：
#   ① 装 Node.js（如果没有）
#   ② 把服务文件写到 /opt/lifekit/
#   ③ 注册成系统服务（开机自启、崩溃自动重启）
#   ④ 开放防火墙端口
#   ⑤ 打印访问地址
#
# 生成时间：2026-10-30T09:02:33.352Z
# 内嵌文件：server.cjs(65518B), licenseCode.cjs(3468B), manage.html(37745B)
# 合计：106731 字节

set -e

PORT="${LIFEKIT_PORT:-8787}"
DIR="/opt/lifekit"
SERVICE="lifekit"

red()  { printf '\033[31m%s\033[0m\n' "$1"; }
grn()  { printf '\033[32m%s\033[0m\n' "$1"; }
ylw()  { printf '\033[33m%s\033[0m\n' "$1"; }

echo ""
echo "══════════════════════════════════════════════"
echo "  安装 LifeKit 管理服务"
echo "══════════════════════════════════════════════"
echo ""

# ── 需要 root ──
if [ "$(id -u)" != "0" ]; then
  red "  × 需要 root 权限。请用： sudo bash install.sh"
  exit 1
fi

# ── ① Node.js ──
echo "[1/5] 检查 Node.js …"
if command -v node >/dev/null 2>&1; then
  grn "  已有：$(node -v)"
else
  ylw "  没装，开始安装（可能要一两分钟）…"
  if command -v apt-get >/dev/null 2>&1; then
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -qq
    apt-get install -y -qq nodejs npm >/dev/null 2>&1 || true
  fi
  if ! command -v node >/dev/null 2>&1; then
    red "  × 自动安装失败。请手动装 Node.js 18+ 后再跑一次："
    echo "      curl -fsSL https://deb.nodesource.com/setup_20.x | bash -"
    echo "      apt-get install -y nodejs"
    exit 1
  fi
  grn "  已安装：$(node -v)"
fi

# 版本要 18+（用到了 node: 前缀与 fetch 相关特性）
NODE_MAJOR="$(node -v | sed 's/v//' | cut -d. -f1)"
if [ "$NODE_MAJOR" -lt 18 ] 2>/dev/null; then
  ylw "  ⚠️ Node 版本偏低（$NODE_MAJOR），建议 18 以上"
fi

# ── ② 写文件 ──
echo "[2/5] 写入服务文件到 $DIR …"
mkdir -p "$DIR"

write_file() {
  # $1=目标文件名
  cat > "$DIR/$1.b64"
  base64 -d "$DIR/$1.b64" > "$DIR/$1"
  rm -f "$DIR/$1.b64"
}

